10 | /// @title Liquidity Book Token
11 | /// @author Trader Joe
12 | /// @notice The LBToken is an implementation of a multi-token.
13 | /// It allows to create multi-ERC20 represented by their ids
14 | contract LBToken is ILBToken {
15 |     using EnumerableSet for EnumerableSet.UintSet;
16 | 
17 |     /// @dev Mapping from token id to account balances
18 |     mapping(uint256 => mapping(address => uint256)) private _balances;
19 | 
20 |     /// @dev Mapping from account to spender approvals
21 |     mapping(address => mapping(address => bool)) private _spenderApprovals;
22 | 
23 |     /// @dev Mapping from token id to total supplies
24 |     mapping(uint256 => uint256) private _totalSupplies;
25 | 
26 |     /// @dev  Mapping from account to set of ids, where user currently have a non-zero balance
27 |     mapping(address => EnumerableSet.UintSet) private _userIds;
28 | 
29 |     string private constant _name = "Liquidity Book Token";
30 |     string private constant _symbol = "LBT";
31 | 
32 |     modifier checkApproval(address _from, address _spender) {
33 |         if (!_isApprovedForAll(_from, _spender)) revert LBToken__SpenderNotApproved(_from, _spender);
34 |         _;
35 |     }
36 | 
37 |     modifier checkAddresses(address _from, address _to) {
38 |         if (_from == address(0) || _to == address(0)) revert LBToken__TransferFromOrToAddress0();
39 |         _;
40 |     }
41 | 
